/** Where the Prisma CLI finds the schema and the database (DATABASE_URL). */
import { defineConfig } from 'prisma/config'

export default defineConfig({
  schema: 'prisma/schema.prisma',
  datasource: { url: process.env.DATABASE_URL ?? 'postgresql://app:app@localhost:5432/app' },
})

files.prisma/schema.prisma:
// Prisma schema of the database, written by DB2CRUD to reflect it: the tables already exist, so do not migrate
// with it. `npm install` generates the client into src/generated/prisma.

generator client {
  provider            = "prisma-client"
  output              = "../src/generated/prisma"
  moduleFormat        = "esm"
  importFileExtension = "js"
}

// The address is in prisma.config.ts (DATABASE_URL); the application connects through src/database.ts
datasource db {
  provider = "postgresql"
}

model Customer {
  id           BigInt   @id @default(autoincrement())
  email        String   @unique(map: "uq_customers_email") @db.VarChar(120)
  passwordHash String   @map("password_hash")
  createdAt    DateTime @default(now()) @map("created_at") @db.Timestamptz(6)
  orders       Order[]  @relation("Order_customer")

  @@map("customers")
}

model Category {
  id       BigInt    @id @default(autoincrement())
  name     String    @unique @db.VarChar(60)
  products Product[] @relation("Product_category")

  @@map("categories")
}

/// CHECK (price >= 0): Prisma does not keep CHECK constraints; the services check them
model Product {
  id          BigInt       @id @default(autoincrement())
  categoryId  BigInt       @map("category_id")
  name        String       @db.VarChar(100)
  price       Decimal      @db.Decimal(10, 2)
  status      String       @db.VarChar(10)
  version     Int          @default(1)
  deletedAt   DateTime?    @map("deleted_at") @db.Timestamptz(6)
  category    Category     @relation("Product_category", fields: [categoryId], references: [id], onDelete: NoAction, onUpdate: NoAction, map: "fk_products_category")
  orderLines  OrderLine[]  @relation("OrderLine_product")
  productTags ProductTag[] @relation("ProductTag_product")

  @@index([status], map: "ix_products_status")
  @@index([categoryId])
  @@map("products")
}

model Order {
  id         BigInt      @id @default(autoincrement())
  customerId BigInt      @map("customer_id")
  placedAt   DateTime    @default(now()) @map("placed_at") @db.Timestamptz(6)
  customer   Customer    @relation("Order_customer", fields: [customerId], references: [id], onDelete: NoAction, onUpdate: NoAction)
  orderLines OrderLine[] @relation("OrderLine_order")

  @@map("orders")
}

model OrderLine {
  orderId   BigInt  @map("order_id")
  line      Int
  productId BigInt  @map("product_id")
  quantity  Int
  order     Order   @relation("OrderLine_order", fields: [orderId], references: [id], onDelete: Cascade, onUpdate: NoAction)
  product   Product @relation("OrderLine_product", fields: [productId], references: [id], onDelete: Restrict, onUpdate: NoAction)

  @@id([orderId, line])
  @@map("order_lines")
}

model Tag {
  id          BigInt       @id @default(autoincrement())
  label       String       @db.VarChar(30)
  productTags ProductTag[] @relation("ProductTag_tag")

  @@map("tags")
}

model ProductTag {
  productId BigInt  @map("product_id")
  tagId     BigInt  @map("tag_id")
  product   Product @relation("ProductTag_product", fields: [productId], references: [id], onDelete: Cascade, onUpdate: NoAction)
  tag       Tag     @relation("ProductTag_tag", fields: [tagId], references: [id], onDelete: Cascade, onUpdate: NoAction)

  @@id([productId, tagId])
  @@map("product_tags")
}

/// The table has no primary key: Prisma needs a unique set of fields, so rows are told apart by all of them,
/// for reading only (the tests create that unique index; the database keeps none)
model AuditLog {
  at      DateTime @db.Timestamptz(6)
  message String

  @@unique([at, message])
  @@map("audit_log")
}

