/** The Prisma client of the PostgreSQL database DATABASE_URL names (see .env.example). */
import { PrismaPg } from '@prisma/adapter-pg'
import { PrismaClient } from './generated/prisma/client.js'

export const DATABASE_URL = process.env.DATABASE_URL ?? 'postgresql://app:app@localhost:5432/app'

/** A client for the PostgreSQL database at `url`. Close it with $disconnect(). */
export function createClient(url: string = DATABASE_URL): PrismaClient {
  return new PrismaClient({ adapter: new PrismaPg({ connectionString: url }) })
}

