/** Repository of the "audit_log" table: reads and writes rows, and decides nothing. */
import { AuditLog } from '../entities/audit-log.js'
import { Prisma } from '../generated/prisma/client.js'
import type { Page } from '../paging.js'

/** The AuditLog of a row Prisma read. */
function toEntity(row: Prisma.AuditLogModel): AuditLog {
  return Object.assign(new AuditLog(), {
    at: row.at,
    message: row.message,
  })
}

/** Keeps audit_log rows in the database, through a Prisma client. Every write is committed at once. */
export class SqlAuditLogRepository {
  constructor(private readonly db: Prisma.TransactionClient) {}

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<AuditLog>> {
    const rows = await this.db.auditLog.findMany({ orderBy: [{ at: 'asc' }, { message: 'asc' }], skip: offset, take: limit })
    const total = await this.db.auditLog.count()
    return { items: rows.map(toEntity), total, offset, limit }
  }
}

