/** Repository of the "categories" table: reads and writes rows, and decides nothing. */
import { Category } from '../entities/category.js'
import { ConflictError } from '../errors.js'
import { Prisma } from '../generated/prisma/client.js'
import type { Page } from '../paging.js'

/** The Category of a row Prisma read. */
function toEntity(row: Prisma.CategoryModel): Category {
  return Object.assign(new Category(), {
    id: Number(row.id),
    name: row.name,
  })
}

/** The values of a new row; those left undefined take the database's default. */
function createData(entity: Category): Prisma.CategoryUncheckedCreateInput {
  return {
    id: entity.id,
    name: entity.name,
  }
}

/** The values a change writes: not the key, nor what the database fills. */
function updateData(entity: Category): Prisma.CategoryUncheckedUpdateManyInput {
  return {
    name: entity.name,
  }
}

/** Keeps categories rows in the database, through a Prisma client. Every write is committed at once. */
export class SqlCategoryRepository {
  constructor(private readonly db: Prisma.TransactionClient) {}

  /** The row with this primary key, or null. */
  async getById(id: number): Promise<Category | null> {
    const row = await this.db.category.findFirst({ where: { id } })
    return row === null ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Category>> {
    const rows = await this.db.category.findMany({ orderBy: { id: 'asc' }, skip: offset, take: limit })
    const total = await this.db.category.count()
    return { items: rows.map(toEntity), total, offset, limit }
  }

  /** The row with this name, or null. */
  async getByName(name: string): Promise<Category | null> {
    const row = await this.db.category.findFirst({ where: { name } })
