        if (creating || 'price' in values) errors.push({ field: 'price', message: 'is required' })
      } else {
        if (!(Number(value) >= 0)) errors.push({ field: 'price', message: 'must be >= 0' })
      }
    }
    {
      const value = values.status
      if (value == null) {
        if (creating || 'status' in values) errors.push({ field: 'status', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 10) errors.push({ field: 'status', message: 'is longer than 10 characters' })
      }
    }
    {
      const value = values.version
      if (value == null) {
        if ('version' in values && !creating) errors.push({ field: 'version', message: 'cannot be empty' })
      }
    }
    {
      const categoryId = 'categoryId' in values ? values.categoryId : current?.categoryId
      if (categoryId != null && (await uow.categories.getById(categoryId as number)) === null)
