  async updateProduct(id: number, changes: Partial<Product>, version: number): Promise<Product> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (current.version !== version)
        throw new ConflictError('Product', 'was changed by someone else since it was read', ['version'])
      await this.check(uow, values, current)
      Object.assign(current, values)
      current.version = version + 1
      const updated = await uow.products.update(current)
      return updated
    })
  }

