      if ((await uow.products.getById(productId)) === null) throw new NotFoundError('Product', productId)
      if (await uow.productTags.getByProductIdAndTagId(productId, tagId) !== null) throw new ConflictError('Tag', 'is already linked to this Product', ['productId'])
      await uow.productTags.insert(Object.assign(new ProductTag(), { tagId, productId }))
    })
  }

  /** Removes the link between a Tag and a Product (product_tags). */
  async removeProduct(tagId: number, productId: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const link = await uow.productTags.getByProductIdAndTagId(productId, tagId)
      if (link === null) throw new NotFoundError('ProductTag', [productId, tagId])
      await uow.productTags.delete(link)
    })
  }
}

